def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_def_count = 0
    opp_def_count = 0
    for a in me:
        if a == 'D':
            my_def_count += 1
    for a in opp:
        if a == 'D':
            opp_def_count += 1
    opp_def_rate = opp_def_count / n

    if opp_def_rate > 0.6:
        return 'D'

    last_me = me[-1]
    last_opp = opp[-1]

    has_retaliated = False
    for i in range(n - 1):
        if me[i] == 'D' and opp[i+1] == 'D':
            has_retaliated = True
            break

    if opp_def_rate < 0.3 and not has_retaliated:
        if n >= 95:
            return 'D' if rng.random() < 0.8 else 'C'
        if my_def_count == 0:
            if n >= 10 and rng.random() < 0.3:
                return 'D'
            return 'C'
        else:
            if last_me == 'D':
                return 'C'
            p = 0.2 + 0.1 * (n / 100.0)
            if p > 0.3:
                p = 0.3
            if rng.random() < p:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        else:
            if opp_def_rate < 0.2 and rng.random() < 0.5:
                return 'C'
            return 'D'
    else:
        return 'C'
